import React, { useState } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faShoppingCart } from '@fortawesome/free-solid-svg-icons';
import './ZapatosCard.css';

const ZapatosCard = () => {
  const [tallaSeleccionada, setTallaSeleccionada] = useState('');
  const [colorSeleccionado, setColorSeleccionado] = useState('');
  const [menuDesplegado, setMenuDesplegado] = useState(false);


  const handleColorChange = (color) => {
    setColorSeleccionado(color);
  };

  const toggleMenu = () => {
    setMenuDesplegado(!menuDesplegado);
  };


  return (
    <div className="zapatos-card">
      <img
        src="https://res.cloudinary.com/dzb3dwute/image/upload/v1718542606/cld-sample-5.jpg"
        alt="Zapato"
        className="zapatos-image"
      />
      <div className="zapatos-info">
        <h3 className="zapatos-name">Nombre del zapato</h3>
        <p className="zapatos-description">Descripción del zapato</p>
        <p className="zapatos-price">$100</p>
        <div className="dropdown">
          <button className="zapatos-btn" onClick={toggleMenu}>
            <FontAwesomeIcon icon={faShoppingCart} className="cart-icon" />
            Agregar al carrito
          </button>
          {menuDesplegado && (
            <div className="dropdown-content">
              <select onChange={(e) => handleTallaChange(e.target.value)}>
                <option value="">Seleccione talla</option>
                {Array.from(Array(9).keys()).map((num) => (
                  <option key={num} value={36 + num}>{36 + num}</option>
                ))}
              </select>
              <div className="dropdown-item" onClick={() => handleColorChange('Convionado')}>Color Convionado</div>
              <div className="dropdown-item" onClick={() => handleColorChange('Joro')}>Color Joro</div>
              <div className="dropdown-item" onClick={() => handleColorChange('Negro')}>Color Negro</div>
              <div className="dropdown-item" onClick={() => handleColorChange('Azul')}>Color Azul</div>
              <div className="dropdown-item" onClick={() => handleColorChange('Verde')}>Color Verde</div>
              <div className="dropdown-item" onClick={() => handleColorChange('Cafe')}>Color Café</div>
              <div className="dropdown-item" onClick={() => handleColorChange('Gris')}>Color Gris</div>
            </div>
          )}
        </div>
        <p>Talla seleccionada: {tallaSeleccionada}</p>
        <p>Color seleccionado: {colorSeleccionado}</p>
      </div>
    </div>
  );
}

export default ZapatosCard;
